// Generated by scripts/build_studies_core.py from the lab's ST solver.
const ST = (() => {
  const NG = 2;

  const CASES = {
    sod:    { label: "Sod", WL: [1.0, 0.0, 1.0],    WR: [0.125, 0.0, 0.1], x0: 0.5, tEnd: 0.25 },
    "123":  { label: "123 problem", WL: [1.0, -2.0, 0.4], WR: [1.0, 2.0, 0.4], x0: 0.5, tEnd: 0.15 },
    blast:  { label: "Strong blast", WL: [1.0, 0.0, 1000.0], WR: [1.0, 0.0, 0.01], x0: 0.5, tEnd: 0.012 },
    modsod: { label: "Modified Sod", WL: [1.0, 0.75, 1.0], WR: [0.125, 0.0, 0.1], x0: 0.3, tEnd: 0.2 },
  };

  // ---------- limiters (Toro §14.3.1) ----------
  const LIMITERS = {
    none: () => 0,
    minmod: r => Math.max(0, Math.min(1, r)),
    vanleer: r => (r + Math.abs(r)) / (1 + Math.abs(r)),
    superbee: r => Math.max(0, Math.min(2 * r, 1), Math.min(r, 2)),
  };

  // ---------- fluxes: all take primitive face states, write into out[3] ----------
  function physFlux(r, u, p, g, out) {
    const E = p / (g - 1) + 0.5 * r * u * u;
    out[0] = r * u; out[1] = r * u * u + p; out[2] = u * (E + p);
  }
  const fl = [0, 0, 0], fr = [0, 0, 0];

  function rusanov(rL, uL, pL, rR, uR, pR, g, out) {
    physFlux(rL, uL, pL, g, fl); physFlux(rR, uR, pR, g, fr);
    const aL = Math.sqrt(g * pL / rL), aR = Math.sqrt(g * pR / rR);
    const S = Math.max(Math.abs(uL) + aL, Math.abs(uR) + aR);
    const EL = pL / (g - 1) + 0.5 * rL * uL * uL, ER = pR / (g - 1) + 0.5 * rR * uR * uR;
    out[0] = 0.5 * (fl[0] + fr[0]) - 0.5 * S * (rR - rL);
    out[1] = 0.5 * (fl[1] + fr[1]) - 0.5 * S * (rR * uR - rL * uL);
    out[2] = 0.5 * (fl[2] + fr[2]) - 0.5 * S * (ER - EL);
  }

  function roeAvg(rL, uL, pL, rR, uR, pR, g) {
    const wL = Math.sqrt(rL), wR = Math.sqrt(rR);
    const HL = (pL / (g - 1) + 0.5 * rL * uL * uL + pL) / rL;
    const HR = (pR / (g - 1) + 0.5 * rR * uR * uR + pR) / rR;
    const u = (wL * uL + wR * uR) / (wL + wR);
    const H = (wL * HL + wR * HR) / (wL + wR);
    return [u, H, Math.sqrt((g - 1) * (H - 0.5 * u * u))];
  }

  function harten(lam, d) { const a = Math.abs(lam); return a < d ? (lam * lam + d * d) / (2 * d) : a; }

  function makeRoe(entropyFix, deltaFactor) {
    return function roe(rL, uL, pL, rR, uR, pR, g, out) {
      const [u, H, a] = roeAvg(rL, uL, pL, rR, uR, pR, g);
      physFlux(rL, uL, pL, g, fl); physFlux(rR, uR, pR, g, fr);
      const EL = pL / (g - 1) + 0.5 * rL * uL * uL, ER = pR / (g - 1) + 0.5 * rR * uR * uR;
      const du1 = rR - rL, du2 = rR * uR - rL * uL, du3 = ER - EL;
      const a2 = (g - 1) / (a * a) * (du1 * (H - u * u) + u * du2 - du3);
      const a1 = 1 / (2 * a) * (du1 * (u + a) - du2 - a * a2);
      const a3 = du1 - (a1 + a2);
      let l1 = Math.abs(u - a), l3 = Math.abs(u + a);
      if (entropyFix) { const d = deltaFactor * a; l1 = harten(u - a, d); l3 = harten(u + a, d); }
      const l2 = Math.abs(u);
      out[0] = 0.5 * (fl[0] + fr[0]) - 0.5 * (l1 * a1 + l2 * a2 + l3 * a3);
      out[1] = 0.5 * (fl[1] + fr[1]) - 0.5 * (l1 * a1 * (u - a) + l2 * a2 * u + l3 * a3 * (u + a));
      out[2] = 0.5 * (fl[2] + fr[2]) - 0.5 * (l1 * a1 * (H - u * a) + l2 * a2 * 0.5 * u * u + l3 * a3 * (H + u * a));
    };
  }

  function hllc(rL, uL, pL, rR, uR, pR, g, out) {
    const aL = Math.sqrt(g * pL / rL), aR = Math.sqrt(g * pR / rR);
    const [ur, , ar] = roeAvg(rL, uL, pL, rR, uR, pR, g);
    const SL = Math.min(uL - aL, ur - ar), SR = Math.max(uR + aR, ur + ar);
    physFlux(rL, uL, pL, g, fl); physFlux(rR, uR, pR, g, fr);
    if (0 <= SL) { out[0] = fl[0]; out[1] = fl[1]; out[2] = fl[2]; return; }
    const Ss = (pR - pL + rL * uL * (SL - uL) - rR * uR * (SR - uR)) / (rL * (SL - uL) - rR * (SR - uR));
    let r, u, p, S, f;
    if (Ss >= 0) { r = rL; u = uL; p = pL; S = SL; f = fl; }
    else if (SR >= 0) { r = rR; u = uR; p = pR; S = SR; f = fr; }
    else { out[0] = fr[0]; out[1] = fr[1]; out[2] = fr[2]; return; }
    const E = p / (g - 1) + 0.5 * r * u * u;
    const c = r * (S - u) / (S - Ss);
    const us0 = c, us1 = c * Ss, us2 = c * (E / r + (Ss - u) * (Ss + p / (r * (S - u))));
    out[0] = f[0] + S * (us0 - r); out[1] = f[1] + S * (us1 - r * u); out[2] = f[2] + S * (us2 - E);
  }

  function getFlux(name, opts) {
    if (name === "rusanov") return rusanov;
    if (name === "hllc") return hllc;
    if (name === "roe") return makeRoe(opts.entropyFix !== false, opts.deltaFactor ?? 0.1);
    throw new Error("unknown flux " + name);
  }

  // ---------- exact Riemann solver (Toro ch. 4) ----------
  function presFn(p, rK, pK, aK, g) {
    if (p > pK) {
      const A = 2 / ((g + 1) * rK), B = (g - 1) / (g + 1) * pK, root = Math.sqrt(A / (p + B));
      return [(p - pK) * root, root * (1 - 0.5 * (p - pK) / (p + B))];
    }
    const z = (g - 1) / (2 * g);
    return [2 * aK / (g - 1) * (Math.pow(p / pK, z) - 1), 1 / (rK * aK) * Math.pow(p / pK, -(g + 1) / (2 * g))];
  }

  function starState(WL, WR, g) {
    const [rL, uL, pL] = WL, [rR, uR, pR] = WR;
    const aL = Math.sqrt(g * pL / rL), aR = Math.sqrt(g * pR / rR), du = uR - uL;
    if (du >= 2 * (aL + aR) / (g - 1)) throw new Error("These states generate vacuum, which the exact solver does not support.");
    const z = (g - 1) / (2 * g);
    let p = Math.pow((aL + aR - 0.5 * (g - 1) * du) / (aL / Math.pow(pL, z) + aR / Math.pow(pR, z)), 1 / z);
    const tol = 1e-8;
    for (let k = 0; k < 100; k++) {
      const [fL, dL] = presFn(p, rL, pL, aL, g), [fR, dR] = presFn(p, rR, pR, aR, g);
      let pn = Math.max(p - (fL + fR + du) / (dL + dR), tol);
      const conv = 2 * Math.abs(pn - p) / (pn + p) < tol;
      p = pn;
      if (conv) break;
    }
    const fL = presFn(p, rL, pL, aL, g)[0], fR = presFn(p, rR, pR, aR, g)[0];
    return [p, 0.5 * (uL + uR) + 0.5 * (fR - fL)];
  }

  function sampleOne(xi, WL, WR, ps, us, g) {
    const [rL, uL, pL] = WL, [rR, uR, pR] = WR;
    const aL = Math.sqrt(g * pL / rL), aR = Math.sqrt(g * pR / rR);
    const g1 = (g - 1) / (2 * g), g2 = (g + 1) / (2 * g), g5 = 2 / (g + 1), g6 = (g - 1) / (g + 1), g7 = 0.5 * (g - 1);
    if (xi <= us) {
      if (ps > pL) {
        const S = uL - aL * Math.sqrt(g2 * ps / pL + g1);
        return xi <= S ? [rL, uL, pL] : [rL * (ps / pL + g6) / (g6 * ps / pL + 1), us, ps];
      }
      const SH = uL - aL, ST_ = us - aL * Math.pow(ps / pL, g1);
      if (xi <= SH) return [rL, uL, pL];
      if (xi > ST_) return [rL * Math.pow(ps / pL, 1 / g), us, ps];
      const c = g5 * (aL + g7 * (uL - xi));
      return [rL * Math.pow(c / aL, 2 / (g - 1)), g5 * (aL + g7 * uL + xi), pL * Math.pow(c / aL, 2 * g / (g - 1))];
    }
    if (ps > pR) {
      const S = uR + aR * Math.sqrt(g2 * ps / pR + g1);
      return xi >= S ? [rR, uR, pR] : [rR * (ps / pR + g6) / (g6 * ps / pR + 1), us, ps];
    }
    const SH = uR + aR, ST_ = us + aR * Math.pow(ps / pR, g1);
    if (xi >= SH) return [rR, uR, pR];
    if (xi < ST_) return [rR * Math.pow(ps / pR, 1 / g), us, ps];
    const c = g5 * (aR - g7 * (uR - xi));
    return [rR * Math.pow(c / aR, 2 / (g - 1)), g5 * (-aR + g7 * uR + xi), pR * Math.pow(c / aR, 2 * g / (g - 1))];
  }

  function exact(xs, t, cs, g = 1.4) {
    const n = xs.length, r = new Float64Array(n), u = new Float64Array(n), p = new Float64Array(n);
    if (t <= 0) {
      for (let i = 0; i < n; i++) { const W = xs[i] <= cs.x0 ? cs.WL : cs.WR; r[i] = W[0]; u[i] = W[1]; p[i] = W[2]; }
      return { rho: r, u, p };
    }
    const [ps, us] = starState(cs.WL, cs.WR, g);
    for (let i = 0; i < n; i++) { const W = sampleOne((xs[i] - cs.x0) / t, cs.WL, cs.WR, ps, us, g); r[i] = W[0]; u[i] = W[1]; p[i] = W[2]; }
    return { rho: r, u, p };
  }

  // ---------- finite-volume solver ----------
  function solve(cs, o = {}) {
    const g = 1.4, N = o.N ?? 400, lim = o.limiter ?? "none";
    const second = lim !== "none";
    const cfl = o.cfl ?? (second ? 0.5 : 0.8);
    const stages = second ? [[0, 1], [0.5, 0.5]] : [[0, 1]];
    const flux = getFlux(o.flux ?? "rusanov", o), phi = LIMITERS[lim];
    const tEnd = o.tEnd ?? cs.tEnd, nFrames = o.frames ?? 0;
    const dx = 1 / N, M = N + 2 * NG, nF = N + 1;
    const x = new Float64Array(N);
    for (let i = 0; i < N; i++) x[i] = (i + 0.5) * dx;

    // conserved state U (3 rows), stage buffer, work arrays
    const U = [new Float64Array(N), new Float64Array(N), new Float64Array(N)];
    for (let i = 0; i < N; i++) {
      const W = x[i] < cs.x0 ? cs.WL : cs.WR;
      U[0][i] = W[0]; U[1][i] = W[0] * W[1]; U[2][i] = W[2] / (g - 1) + 0.5 * W[0] * W[1] * W[1];
    }
    const totals = () => U.map(row => row.reduce((a,b) => a+b, 0) * dx);
    const initialTotals = totals(), boundaryFlux = [0, 0, 0];
    const Us = [new Float64Array(N), new Float64Array(N), new Float64Array(N)];
    const Wg = [new Float64Array(M), new Float64Array(M), new Float64Array(M)];
    const slope = [new Float64Array(M), new Float64Array(M), new Float64Array(M)];
    const F = [new Float64Array(nF), new Float64Array(nF), new Float64Array(nF)];
    const out = [0, 0, 0];
    let nFallback = 0;

    const prim = (U_) => {
      const W = [new Float64Array(N), new Float64Array(N), new Float64Array(N)];
      for (let i = 0; i < N; i++) {
        const r = U_[0][i], u = U_[1][i] / r;
        W[0][i] = r; W[1][i] = u; W[2][i] = (g - 1) * (U_[2][i] - 0.5 * r * u * u);
      }
      return W;
    };

    function operator(Uin, L) {
      for (let j = 0; j < M; j++) {
        const i = Math.min(Math.max(j - NG, 0), N - 1);
        const r = Uin[0][i], u = Uin[1][i] / r;
        Wg[0][j] = r; Wg[1][j] = u; Wg[2][j] = (g - 1) * (Uin[2][i] - 0.5 * r * u * u);
      }
      for (let j = 1; j < M - 1; j++) {
        for (let v = 0; v < 3; v++) {
          const dm = Wg[v][j] - Wg[v][j - 1], dp = Wg[v][j + 1] - Wg[v][j];
          const r = dm !== 0 ? dp / dm : 0;
          slope[v][j] = phi(r) * dm;
        }
        const rm = Wg[0][j] - 0.5 * slope[0][j], rp = Wg[0][j] + 0.5 * slope[0][j];
        const pm = Wg[2][j] - 0.5 * slope[2][j], pp = Wg[2][j] + 0.5 * slope[2][j];
        if (second && (rm <= 0 || rp <= 0 || pm <= 0 || pp <= 0)) { slope[0][j] = slope[1][j] = slope[2][j] = 0; nFallback++; }
      }
      for (let k = 0; k < nF; k++) {
        const a = k + 1, b = k + 2; // face between padded cells a and b
        flux(Wg[0][a] + 0.5 * slope[0][a], Wg[1][a] + 0.5 * slope[1][a], Wg[2][a] + 0.5 * slope[2][a],
             Wg[0][b] - 0.5 * slope[0][b], Wg[1][b] - 0.5 * slope[1][b], Wg[2][b] - 0.5 * slope[2][b], g, out);
        F[0][k] = out[0]; F[1][k] = out[1]; F[2][k] = out[2];
      }
      for (let v = 0; v < 3; v++) for (let i = 0; i < N; i++) L[v][i] = -(F[v][i + 1] - F[v][i]) / dx;
    }

    function badCell(U_) {
      for (let i = 0; i < N; i++) {
        const r = U_[0][i], u = U_[1][i] / r, p = (g - 1) * (U_[2][i] - 0.5 * r * u * u);
        if (!(r > 0 && p > 0)) return { cell: i, x: x[i], rho: r, p };
      }
      return null;
    }

    const L = [new Float64Array(N), new Float64Array(N), new Float64Array(N)];
    const frames = [];
    const snap = (t) => { const W = prim(U); frames.push({ t, rho: W[0], u: W[1], p: W[2] }); };
    let nextFrame = 0;
    const frameTime = k => tEnd * k / nFrames;
    if (nFrames) { snap(0); nextFrame = 1; }

    let t = 0, steps = 0, failure = null;
    const t0 = (typeof performance !== "undefined" ? performance : Date).now();
    outer:
    while (t < tEnd) {
      let smax = 0;
      for (let i = 0; i < N; i++) {
        const r = U[0][i], u = U[1][i] / r, p = (g - 1) * (U[2][i] - 0.5 * r * u * u);
        smax = Math.max(smax, Math.abs(u) + Math.sqrt(g * p / r));
      }
      const dt = Math.min(cfl * dx / smax, tEnd - t);
      const tNew = tEnd - t <= dt ? tEnd : t + dt;
      for (let v = 0; v < 3; v++) Us[v].set(U[v]);
      const stepFlux = [0, 0, 0];
      for (let s = 0; s < stages.length; s++) {
        const [a, b] = stages[s];
        operator(Us, L);
        // Euler weight 1; SSP-RK2 weights 1/2, 1/2. Commit only accepted steps.
        for (let v = 0; v < 3; v++) stepFlux[v] += dt * (second ? 0.5 : 1) * (F[v][0] - F[v][N]);
        for (let v = 0; v < 3; v++) for (let i = 0; i < N; i++) Us[v][i] = a * U[v][i] + b * (Us[v][i] + dt * L[v][i]);
        const bad = badCell(Us);
        if (bad) { failure = { ...bad, t: tNew, stage: s + 1, step: steps + 1 }; break outer; }
      }
      for (let v = 0; v < 3; v++) U[v].set(Us[v]);
      for (let v = 0; v < 3; v++) boundaryFlux[v] += stepFlux[v];
      t = tNew; steps++;
      while (nFrames && nextFrame <= nFrames && t >= frameTime(nextFrame) - 1e-12) { snap(t); nextFrame++; }
    }
    const ms = (typeof performance !== "undefined" ? performance : Date).now() - t0;
    const W = prim(U);
    const finalTotals = totals();
    const conservation = { initial: initialTotals, final: finalTotals, boundaryFlux,
      residual: finalTotals.map((value,v) => value-initialTotals[v]-boundaryFlux[v]) };
    return { conservation, x, dx, N, t, steps, ms, rho: W[0], u: W[1], p: W[2], frames, failure, nFallback };
  }

  function l1(res, cs, field = "rho") {
    const ex = exact(res.x, res.t, cs);
    let s = 0;
    for (let i = 0; i < res.N; i++) s += Math.abs(res[field][i] - ex[field][i]);
    return s * res.dx;
  }

  // Cells inside the 5–95% band of the shock (in p) and contact (in rho), for left-fan / right-shock cases.
  function resolution(res, cs) {
    const g = 1.4;
    let ps, us;
    try { [ps, us] = starState(cs.WL, cs.WR, g); } catch (e) { return null; }
    const [rL, uL, pL] = cs.WL, [rR, uR, pR] = cs.WR;
    if (!(ps <= pL && ps > pR)) return null;
    const aL = Math.sqrt(g * pL / rL), aR = Math.sqrt(g * pR / rR), t = res.t;
    const tail = cs.x0 + (us - aL * Math.pow(ps / pL, (g - 1) / (2 * g))) * t;
    const contact = cs.x0 + us * t;
    const shock = cs.x0 + (uR + aR * Math.sqrt((g + 1) / (2 * g) * ps / pR + (g - 1) / (2 * g))) * t;
    const mid = 0.5 * (contact + shock);
    const ex = exact([contact - 1e-9, contact + 1e-9], t, cs);
    const count = (q, lo, hi, qa, qb) => {
      let n = 0;
      for (let i = 0; i < res.N; i++) {
        if (res.x[i] > lo && res.x[i] < hi) { const s = (q[i] - qa) / (qb - qa); if (s > 0.05 && s < 0.95) n++; }
      }
      return n;
    };
    return { shock: count(res.p, mid, 1, ps, pR), contact: count(res.rho, tail, mid, ex.rho[0], ex.rho[1]) };
  }

  return { CASES, LIMITERS, solve, exact, starState, l1, resolution };
})();
